+typedef struct {
+    aisoc_dbus_conn_t* dev_conn;
+    ui_gw_server_t* server;
+    volatile bool running;
+} gw_pump_ctx_t;
+
+/**
+ * @brief 后台泵送 DeviceStub D-Bus 线程
+ */
+static void* dev_pump_thread(void* arg) {
+    gw_pump_ctx_t* p = (gw_pump_ctx_t*)arg;
+    while (p->running) {
+        bool disp = false;
+        aisoc_dbus_dispatch_once(p->dev_conn, 5, &disp);
+    }
+    return nullptr;
+}
+
+/**
+ * @brief 后台泵送 HTTP 网关服务线程
+ */
+static void* gw_pump_thread(void* arg) {
+    gw_pump_ctx_t* p = (gw_pump_ctx_t*)arg;
+    while (p->running) {
+        ui_gw_server_step(p->server, 5);
+    }
+    return nullptr;
+}
+
+/**
+ * @brief 发送 HTTP 请求并读取响应
+ */
+static bool send_http_req(uint16_t port, const char* method, const char* path, char* out_rx) {
+    const int fd = socket(AF_INET, SOCK_STREAM, 0);
+    if (fd < 0) return false;
+    struct sockaddr_in addr;
+    std::memset(&addr, 0, sizeof(addr));
+    addr.sin_family = AF_INET;
+    addr.sin_port = htons(port);
+    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
+    if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
+        close(fd);
+        return false;
+    }
+    const char* body = (std::strcmp(method, "POST") == 0) ?
+        "{\"axis\":\"X\",\"step_mm\":12.5,\"active_slot\":2,\"bed\":60.0,\"nozzle\":210.0,\"gcode\":\"G28\"}" : "";
+    char req[512] = {0};
+    std::snprintf(req, sizeof(req),
+                  "%s %s HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Length: %zu\r\n\r\n%s",
+                  method, path, std::strlen(body), body);
+    (void)send(fd, req, std::strlen(req), 0);
+    std::memset(out_rx, 0, 1024U);
+    const ssize_t n = recv(fd, out_rx, 1023U, 0);
+    close(fd);
+    return n > 0;
+}
