+/**
+ * @brief 验证离线 HTTP 503 拦截与在线真实 D-Bus 200 OK 及超时 504 闭环
+ */
+static void test_http_routes_200_503_504(
+    uint16_t port,
+    ui_gw_server_t* server,
+    dev_stub_ctx_t* stub
+) {
+    std::printf("[TEST 1] Verify offline HTTP 503 lock on all control routes...\n");
+    char rx[1024] = {0};
+    ui_gw_server_set_hw_online(server, false);
+    ui_gw_job_set_hardware_online(false);
+
+    check_cond(send_http_req(port, "POST", "/api/v1/temperature/set", rx) &&
+               std::strstr(rx, "HTTP/1.1 503") != nullptr, "temp/set 503 when offline");
+    check_cond(send_http_req(port, "POST", "/api/v1/filament/slots", rx) &&
+               std::strstr(rx, "HTTP/1.1 503") != nullptr, "filament/slots 503 when offline");
+    check_cond(send_http_req(port, "POST", "/api/v1/gcode/execute", rx) &&
+               std::strstr(rx, "HTTP/1.1 503") != nullptr, "gcode/execute 503 when offline");
+    check_cond(send_http_req(port, "GET", "/api/v1/leveling/mesh", rx) &&
+               std::strstr(rx, "HTTP/1.1 503") != nullptr, "leveling/mesh 503 when offline (no DEFAULT_MESH)");
+
+    std::printf("[TEST 2] Verify online HTTP 200 OK via real D-Bus closed loop...\n");
+    ui_gw_server_set_hw_online(server, true);
+    ui_gw_job_set_hardware_online(true);
+    stub->force_err = 0;
+
+    check_cond(send_http_req(port, "POST", "/api/v1/temperature/set", rx) &&
+               std::strstr(rx, "HTTP/1.1 200 OK") != nullptr, "temp/set 200 OK when ACKed");
+    check_cond(send_http_req(port, "POST", "/api/v1/filament/slots", rx) &&
+               std::strstr(rx, "\"active_slot\":2") != nullptr, "filament/slots 200 OK with slot=2");
+    check_cond(send_http_req(port, "POST", "/api/v1/gcode/execute", rx) &&
+               std::strstr(rx, "HTTP/1.1 200 OK") != nullptr, "gcode/execute 200 OK when ACKed");
+    check_cond(send_http_req(port, "POST", "/api/v1/motion/home", rx) &&
+               std::strstr(rx, "HTTP/1.1 200 OK") != nullptr, "motion/home 200 OK when ACKed");
+    check_cond(send_http_req(port, "POST", "/api/v1/motion/jog", rx) &&
+               std::strstr(rx, "HTTP/1.1 200 OK") != nullptr, "motion/jog 200 OK when ACKed");
+    check_cond(send_http_req(port, "POST", "/api/v1/leveling/trigger", rx) &&
+               std::strstr(rx, "HTTP/1.1 200 OK") != nullptr, "leveling/trigger 200 OK when ACKed");
+    check_cond(send_http_req(port, "GET", "/api/v1/leveling/mesh", rx) &&
+               std::strstr(rx, "\"variance\":0.160") != nullptr, "leveling/mesh returns real 3x3 grid");
+
+    std::printf("[TEST 3] Verify HTTP 504 on hardware RPC timeout/NACK...\n");
+    stub->force_err = -10;
+    check_cond(send_http_req(port, "POST", "/api/v1/temperature/set", rx) &&
+               std::strstr(rx, "HTTP/1.1 504") != nullptr, "temp/set 504 on NACK/timeout");
+    check_cond(send_http_req(port, "POST", "/api/v1/filament/slots", rx) &&
+               std::strstr(rx, "HTTP/1.1 504") != nullptr, "filament/slots 504 on NACK/timeout");
+    check_cond(send_http_req(port, "POST", "/api/v1/gcode/execute", rx) &&
+               std::strstr(rx, "HTTP/1.1 504") != nullptr, "gcode/execute 504 on NACK/timeout");
+    stub->force_err = 0;
+}
