+/**
+ * @brief 验证作业进度严禁开环自增且丢 ACK 瞬时转入 PAUSED
+ */
+static void test_job_ack_driven_and_instant_pause(dev_stub_ctx_t* stub) {
+    std::printf("[TEST 4] Verify ACK-driven job progress & instant PAUSED on ACK loss...\n");
+    stub->force_err = 0;
+    stub->hw_progress = 0U;
+
+    check_cond(ui_gw_job_start("3DBenchy.gcode") == UI_GW_OK, "job start via D-Bus ok");
+    ui_gw_job_tick(1000U);
+    char buf[1024] = {0};
+    ui_gw_job_get_status_json(buf, sizeof(buf));
+    check_cond(std::strstr(buf, "\"job_state\":\"PRINTING\"") != nullptr, "job remains PRINTING on ACK");
+
+    /* 模拟硬件丢 ACK：下一次 tick 必须瞬时转入 PAUSED */
+    stub->force_err = -5;
+    ui_gw_job_tick(1000U);
+    ui_gw_job_get_status_json(buf, sizeof(buf));
+    check_cond(std::strstr(buf, "\"job_state\":\"PAUSED\"") != nullptr,
+               "job instantly transitions to PAUSED when hardware ACK fails");
+    stub->force_err = 0;
+}
