+int main(void) {
+    std::printf("=================================================================\n");
+    std::printf("Running TWIN-49 UI Gateway Zero-Mock & Route Verification Suite\n");
+    std::printf("=================================================================\n");
+    ui_gw_job_init();
+    char st_buf[1024] = {0};
+    ui_gw_job_get_status_json(st_buf, sizeof(st_buf));
+    check_cond(std::strstr(st_buf, "\"is_homed\":false") != nullptr, "initial is_homed is false (no fake homed)");
+
+    char custom_addr[256] = {0};
+    const pid_t dbus_pid = spawn_dbus_daemon(custom_addr, sizeof(custom_addr));
+    check_cond(dbus_pid > 0, "spawn_dbus_daemon succeeded");
+    if (dbus_pid > 0) {
+        aisoc_dbus_conn_config_t d_cfg = { AISOC_DBUS_BUS_CUSTOM, custom_addr, false };
+        aisoc_dbus_conn_t dev_conn;
+        aisoc_dbus_conn_init(&d_cfg, &dev_conn);
+        dev_stub_ctx_t stub = { 0, 0, 0, 0, 0U, 0U };
+        register_dev_stub(&dev_conn, &stub);
+        ui_gw_dbus_client_t gw_dbus;
+        check_cond(ui_gw_dbus_init(custom_addr, &gw_dbus) == UI_GW_OK, "ui_gw_dbus_init ok");
+        ui_gw_server_t server;
+        const uint16_t port = 18095U;
+        check_cond(ui_gw_server_init(port, &gw_dbus, nullptr, &server) == UI_GW_OK, "ui_gw_server_init ok");
+        gw_pump_ctx_t pump = { &dev_conn, &server, true };
+        pthread_t dev_tid, gw_tid;
+        pthread_create(&dev_tid, nullptr, dev_pump_thread, &pump);
+        pthread_create(&gw_tid, nullptr, gw_pump_thread, &pump);
+        usleep(50000);
+        test_http_routes_200_503_504(port, &server, &stub);
+        test_job_ack_driven_and_instant_pause(&stub);
+        pump.running = false;
+        pthread_join(gw_tid, nullptr);
+        pthread_join(dev_tid, nullptr);
+        ui_gw_server_close(&server);
+        ui_gw_dbus_close(&gw_dbus);
+        aisoc_dbus_conn_close(&dev_conn);
+        kill(dbus_pid, SIGTERM);
+        waitpid(dbus_pid, nullptr, 0);
+    }
+    std::printf("Results: %d passed, %d failed\n", g_pass_cnt, g_fail_cnt);
+    return (g_fail_cnt == 0) ? 0 : 1;
+}
