+typedef struct {
+    int master_fd;
+    volatile bool running;
+    volatile bool nack_th;
+    volatile bool drop_th;
+} pty_mcu_responder_t;
+
+/**
+ * @brief 填充 PTY 响应载荷
+ */
+static size_t fill_pty_resp_payload(
+    const minimc::FrameView* req_f,
+    uint8_t* out_cmd,
+    uint8_t* pl
+) {
+    const uint8_t cmd = req_f->header.cmd_id;
+    *out_cmd = cmd;
+    if (cmd == MINIMC_CMD_SET_TEMP || cmd == MINIMC_CMD_TEMP_QUERY) {
+        *out_cmd = MINIMC_CMD_TEMP_REPORT;
+        minimc_temp_wire_payload_t tr = {};
+        tr.current_temp_deci_c = 600;
+        tr.target_temp_deci_c = 600;
+        std::memcpy(pl, &tr, sizeof(tr));
+        return sizeof(tr);
+    }
+    if (cmd == MINIMC_CMD_MOTION_HOME || cmd == MINIMC_CMD_MOTION_MOVE || cmd == MINIMC_CMD_POS_QUERY) {
+        *out_cmd = MINIMC_CMD_POS_QUERY;
+        minimc_pos_resp_t pr = { 1250, 2500, 40, 10, 0U, 0x07U, 0U };
+        std::memcpy(pl, &pr, sizeof(pr));
+        return sizeof(pr);
+    }
+    if (cmd == MINIMC_CMD_JOB_CONTROL) {
+        minimc_job_resp_t jr = { req_f->payload.data[0], 0U, 100U, 35U };
+        std::memcpy(pl, &jr, sizeof(jr));
+        return sizeof(jr);
+    }
+    if (cmd == MINIMC_CMD_LEVEL_GRID_QUERY || cmd == MINIMC_CMD_LEVEL_TRIGGER) {
+        *out_cmd = MINIMC_CMD_LEVEL_GRID_QUERY;
+        minimc_level_grid_wire_payload_t gr = {};
+        gr.grid_points_x = 5U;
+        gr.grid_points_y = 5U;
+        for (int i = 0; i < 9; ++i) gr.z_offset_um[i] = (int16_t)((i - 4) * 10);
+        std::memcpy(pl, &gr, sizeof(gr));
+        return sizeof(gr);
+    }
+    if (cmd == MINIMC_CMD_SLOT_SELECT) {
+        minimc_filament_resp_t fr = { req_f->payload.data[0], 0x0FU, 2U, 0U };
+        std::memcpy(pl, &fr, sizeof(fr));
+        return sizeof(fr);
+    }
+    if (cmd == MINIMC_CMD_GCODE_EXEC) {
+        minimc_gcode_resp_t gc = { 0U, 8U, req_f->header.seq };
+        std::memcpy(pl, &gc, sizeof(gc));
+        return sizeof(gc);
+    }
+    *out_cmd = MINIMC_CMD_ACK;
+    return 0U;
+}
+
+/**
+ * @brief 向 PTY 写入指定 MiniMCProto 响应帧
+ */
+static void send_pty_resp(int fd, const minimc::FrameView* req_f) {
+    uint8_t pl[64] = {0};
+    uint8_t out_cmd = req_f->header.cmd_id;
+    const size_t pl_len = fill_pty_resp_payload(req_f, &out_cmd, pl);
+    minimc::FrameHeader hdr = {};
+    hdr.sof_1 = MINIMC_SOF_1;
+    hdr.sof_2 = MINIMC_SOF_2;
+    hdr.src_id = req_f->header.dst_id;
+    hdr.dst_id = MINIMC_DEV_AP;
+    hdr.flags = MINIMC_RESP_FLAGS_V2;
+    hdr.cmd_id = out_cmd;
+    hdr.hop_limit = 10U;
+    hdr.seq = req_f->header.seq;
+    hdr.payload_len = (uint16_t)pl_len;
+    uint8_t out_buf[128] = {0};
+    minimc::Bytes p(pl, pl_len);
+    minimc::MutableBytes m(out_buf, sizeof(out_buf));
+    size_t enc_len = 0U;
+    if (minimc::encode_frame(hdr, p, m, &enc_len) == minimc::Status::OK) {
+        (void)write(fd, out_buf, enc_len);
+    }
+}
+
+/**
+ * @brief 发送 NACK (flags 含 0x08 NACK 标志) 帧至 PTY
+ */
+static void send_pty_nack(int fd, const minimc::FrameView* req_f) {
+    uint8_t err_pl[1] = { 0x04U };
+    minimc::FrameHeader hdr = {};
+    hdr.sof_1 = MINIMC_SOF_1;
+    hdr.sof_2 = MINIMC_SOF_2;
+    hdr.src_id = req_f->header.dst_id;
+    hdr.dst_id = MINIMC_DEV_AP;
+    hdr.flags = MINIMC_RESP_FLAGS_V2;
+    hdr.cmd_id = MINIMC_CMD_NACK;
+    hdr.hop_limit = 10U;
+    hdr.seq = req_f->header.seq;
+    hdr.payload_len = 1U;
+    uint8_t out_buf[64] = {0};
+    minimc::Bytes p(err_pl, 1U);
+    minimc::MutableBytes m(out_buf, sizeof(out_buf));
+    size_t enc_len = 0U;
+    if (minimc::encode_frame(hdr, p, m, &enc_len) == minimc::Status::OK) {
+        (void)write(fd, out_buf, enc_len);
+    }
+}
+
+/**
+ * @brief PTY 虚拟双 MCU 响应线程
+ */
+static void* pty_responder_thread(void* arg) {
+    pty_mcu_responder_t* ctx = (pty_mcu_responder_t*)arg;
+    minimc::StreamParser parser;
+    minimc::parser_init(&parser);
+    uint8_t rx[128];
+    while (ctx->running) {
+        const ssize_t n = read(ctx->master_fd, rx, sizeof(rx));
+        if (n <= 0) {
+            usleep(2000);
+            continue;
+        }
+        for (ssize_t i = 0; i < n; ++i) {
+            minimc::FrameView pf = {};
+            bool ready = false;
+            if (minimc::parser_feed_byte(&parser, rx[i], 0U, &pf, &ready) == minimc::Status::OK && ready) {
+                if (pf.header.dst_id == 0x03U && ctx->drop_th) {
+                    continue;
+                }
+                if (pf.header.dst_id == 0x03U && ctx->nack_th) {
+                    send_pty_nack(ctx->master_fd, &pf);
+                    continue;
+                }
+                send_pty_resp(ctx->master_fd, &pf);
+            }
+        }
+    }
+    return nullptr;
+}
